eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   PROBLEM_ITEMS: () => (/* binding */ PROBLEM_ITEMS)\n/* harmony export */ });\nconst PROBLEM_ITEMS = [\n    // Programming & Algorithms\n    {\n        id: \"prob-1\",\n        title: \"Two Sum: Find Indices of Target Pair\",\n        category: \"Programming\",\n        difficulty: \"Easy\",\n        xp: 50,\n        solved: true,\n        tags: [\n            \"Array\",\n            \"Hash Table\",\n            \"Two Pointers\"\n        ],\n        description: \"Given an array of integers `nums` and an integer `target`, return indices of the two numbers such that they add up to `target`. You may assume that each input would have exactly one solution, and you may not use the same element twice.\",\n        examples: [\n            {\n                input: \"nums = [2,7,11,15], target = 9\",\n                output: \"[0,1]\",\n                explanation: \"Because nums[0] + nums[1] == 9, we return [0, 1].\"\n            },\n            {\n                input: \"nums = [3,2,4], target = 6\",\n                output: \"[1,2]\"\n            }\n        ],\n        starterCode: `function twoSum(nums: number[], target: number): number[] {\\n  // Write your O(n) hash map solution\\n  return [];\\n}`,\n        solution: `function twoSum(nums: number[], target: number): number[] {\\n  const map = new Map<number, number>();\\n  for (let i = 0; i < nums.length; i++) {\\n    const complement = target - nums[i];\\n    if (map.has(complement)) {\\n      return [map.get(complement)!, i];\\n    }\\n    map.set(nums[i], i);\\n  }\\n  return [];\\n}`,\n        hints: [\n            \"Use a Hash Map to store numbers you have already visited along with their index.\",\n            \"For each number `x`, check if `target - x` exists in the map.\"\n        ]\n    },\n    {\n        id: \"prob-2\",\n        title: \"Longest Substring Without Repeating Characters\",\n        category: \"Algorithms\",\n        difficulty: \"Medium\",\n        xp: 100,\n        solved: true,\n        tags: [\n            \"Sliding Window\",\n            \"String\",\n            \"Hash Set\"\n        ],\n        description: \"Given a string `s`, find the length of the longest substring without repeating characters.\",\n        examples: [\n            {\n                input: \"s = 'abcabcbb'\",\n                output: \"3\",\n                explanation: \"The answer is 'abc', with the length of 3.\"\n            },\n            {\n                input: \"s = 'bbbbb'\",\n                output: \"1\",\n                explanation: \"The answer is 'b', with the length of 1.\"\n            }\n        ],\n        starterCode: `function lengthOfLongestSubstring(s: string): number {\\n  // Implement sliding window\\n  return 0;\\n}`,\n        solution: `function lengthOfLongestSubstring(s: string): number {\\n  const seen = new Set<string>();\\n  let left = 0, maxLength = 0;\\n  for (let right = 0; right < s.length; right++) {\\n    while (seen.has(s[right])) {\\n      seen.delete(s[left]);\\n      left++;\\n    }\\n    seen.add(s[right]);\\n    maxLength = Math.max(maxLength, right - left + 1);\\n  }\\n  return maxLength;\\n}`,\n        hints: [\n            \"Maintain a sliding window `[left, right]` and a Set containing characters in the current window.\",\n            \"When a duplicate is encountered at `right`, increment `left` and remove characters until the duplicate is resolved.\"\n        ]\n    },\n    {\n        id: \"prob-3\",\n        title: \"SQL: Consecutive Active Days Calculation\",\n        category: \"SQL\",\n        difficulty: \"Medium\",\n        xp: 90,\n        solved: false,\n        tags: [\n            \"PostgreSQL\",\n            \"Window Functions\",\n            \"Gaps and Islands\"\n        ],\n        description: \"Given an `activity_log` table with columns `(user_id, activity_date)`, write a SQL query to identify all users who logged in for at least 3 consecutive days.\",\n        examples: [\n            {\n                input: \"activity_log with user 101 on '2026-09-01', '2026-09-02', '2026-09-03'\",\n                output: \"user_id: 101, consecutive_days: 3\"\n            }\n        ],\n        starterCode: `-- Find users with >= 3 consecutive active login dates\\nSELECT user_id\\nFROM activity_log\\nGROUP BY user_id;`,\n        solution: `WITH RankedDates AS (\\n  SELECT DISTINCT user_id, activity_date,\\n    activity_date - (DENSE_RANK() OVER (PARTITION BY user_id ORDER BY activity_date) * INTERVAL '1 day') AS grp\\n  FROM activity_log\\n)\\nSELECT user_id, COUNT(*) as consecutive_days\\nFROM RankedDates\\nGROUP BY user_id, grp\\nHAVING COUNT(*) >= 3;`,\n        hints: [\n            \"Subtract `ROW_NUMBER() * INTERVAL '1 day'` from the date to create a constant island identifier `grp`.\",\n            \"Group by `user_id, grp` and filter with `HAVING COUNT(*) >= 3`.\"\n        ]\n    },\n    {\n        id: \"prob-4\",\n        title: \"Debugging: Node.js Memory Leak in Event Listener\",\n        category: \"Debugging\",\n        difficulty: \"Hard\",\n        xp: 120,\n        solved: false,\n        tags: [\n            \"Node.js\",\n            \"Memory Management\",\n            \"EventEmitter\",\n            \"V8\"\n        ],\n        description: \"A high-traffic WebSocket server's heap memory grows continuously until it crashes with `ERR_WORKER_OUT_OF_MEMORY`. Identify the bug in the client disconnect handler and patch it.\",\n        examples: [\n            {\n                input: \"10,000 WebSocket connect/disconnect cycles\",\n                output: \"Memory stays steady at ~85MB instead of climbing to 1.8GB.\"\n            }\n        ],\n        starterCode: `// Identify the memory leak in this socket handler\\nclass ChatRoom {\\n  onUserConnect(socket: Socket) {\\n    globalEmitter.on('broadcast', (msg) => {\\n      socket.emit('message', msg);\\n    });\\n    socket.on('disconnect', () => {\\n      // Fix missing cleanup\\n    });\\n  }\\n}`,\n        solution: `class ChatRoom {\\n  onUserConnect(socket: Socket) {\\n    const handler = (msg: string) => {\\n      socket.emit('message', msg);\\n    };\\n    globalEmitter.on('broadcast', handler);\\n    socket.on('disconnect', () => {\\n      globalEmitter.off('broadcast', handler);\\n    });\\n  }\\n}`,\n        hints: [\n            \"An anonymous function passed to `globalEmitter.on` retains a closure reference to `socket`, preventing garbage collection on disconnect.\",\n            \"Store the handler function reference and call `globalEmitter.off` on socket disconnect.\"\n        ]\n    },\n    {\n        id: \"prob-5\",\n        title: \"Logical Reasoning: Task Scheduling & Critical Path\",\n        category: \"Logical Reasoning\",\n        difficulty: \"Medium\",\n        xp: 75,\n        solved: true,\n        tags: [\n            \"DAG\",\n            \"Topological Sort\",\n            \"Critical Path\",\n            \"Logic\"\n        ],\n        description: \"Tasks A through F have dependencies: A -> B (2d), A -> C (3d), B -> D (4d), C -> D (2d), D -> E (1d), C -> F (5d). What is the minimum duration required to complete all tasks, and which tasks form the critical path?\",\n        examples: [\n            {\n                input: \"A (1d), B (2d), C (3d), D (4d), E (1d), F (5d)\",\n                output: \"Critical Path: A -> B -> D -> E (Total 8 days)\"\n            }\n        ],\n        starterCode: `function findCriticalPath(tasks: Record<string, { duration: number, deps: string[] }>) {\\n  // Calculate longest path in DAG\\n}`,\n        solution: `// Total duration: 8 days\\n// Path: A (1) + B (2) + D (4) + E (1) = 8 days\\n// Path A (1) + C (3) + F (5) = 9 days (if F is final).`,\n        hints: [\n            \"Calculate the Earliest Start (ES) and Earliest Finish (EF) for each node.\",\n            \"The path with the longest total duration is the Critical Path.\"\n        ]\n    },\n    {\n        id: \"prob-6\",\n        title: \"Aptitude: Data Pipeline Throughput & Latency Model\",\n        category: \"Aptitude\",\n        difficulty: \"Easy\",\n        xp: 60,\n        solved: true,\n        tags: [\n            \"Math\",\n            \"Ratios\",\n            \"Systems Math\",\n            \"Probability\"\n        ],\n        description: \"A distributed microservice receives 24,000 requests per minute. Each server node can handle 250 requests per second with 99% CPU utilization. To maintain a safety buffer of at most 70% CPU utilization, what is the minimum number of worker nodes required?\",\n        examples: [\n            {\n                input: \"24,000 req/min = 400 req/sec total load\",\n                output: \"Minimum nodes: 3 nodes (handling up to 525 req/sec at 70% cap)\"\n            }\n        ],\n        starterCode: `function calculateMinimumNodes(reqPerMin: number, nodeCapPerSec: number, targetCapRatio: number): number {\\n  const reqPerSec = reqPerMin / 60;\\n  const safeNodeCap = nodeCapPerSec * targetCapRatio;\\n  return Math.ceil(reqPerSec / safeNodeCap);\\n}`,\n        solution: `function calculateMinimumNodes(reqPerMin: number, nodeCapPerSec: number, targetCapRatio: number): number {\\n  const reqPerSec = reqPerMin / 60; // 400 req/sec\\n  const safeNodeCap = nodeCapPerSec * targetCapRatio; // 250 * 0.7 = 175 req/sec\\n  return Math.ceil(reqPerSec / safeNodeCap); // Math.ceil(400 / 175) = 3 nodes\\n}`,\n        hints: [\n            \"Convert requests per minute to requests per second (divide by 60).\",\n            \"Calculate effective capacity per node = 250 * 0.70 = 175 req/s.\"\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/problems.ts\n");

