eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   CLOUD_DEVOPS_QUESTIONS: () => (/* binding */ CLOUD_DEVOPS_QUESTIONS)\n/* harmony export */ });\nconst CLOUD_DEVOPS_QUESTIONS = [\n    // 10 MCQs\n    {\n        id: \"do-mcq-01\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Containerization\",\n        subSkill: \"Docker Internals\",\n        topic: \"Linux Namespaces vs Cgroups\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"In Linux container runtimes (like Docker and containerd), which kernel subsystem is responsible for metering and limiting hardware resource consumption (like CPU and RAM limits)?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Namespaces\"\n            },\n            {\n                label: \"B\",\n                text: \"Control Groups (cgroups)\"\n            },\n            {\n                label: \"C\",\n                text: \"SELinux\"\n            },\n            {\n                label: \"D\",\n                text: \"AppArmor\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`cgroups` (control groups) isolate and constrain hardware resource utilization (CPU, memory, disk I/O), whereas `namespaces` isolate what a process can see (process IDs, network interfaces, mount points).\",\n        source: \"IndiaBIX Technical Interview - UNIX & Operating Systems\",\n        sourceUrl: \"https://www.indiabix.com/technical/operating-systems/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-02\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Infrastructure as Code\",\n        subSkill: \"Terraform\",\n        topic: \"State File Locking\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"Why should teams using Terraform store state files in a remote backend (like AWS S3) accompanied by a state locking mechanism (like DynamoDB)?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"To prevent multiple team members or CI jobs from executing concurrent writes that could corrupt the infrastructure state file.\"\n            },\n            {\n                label: \"B\",\n                text: \"To convert HCL code automatically into Python scripts.\"\n            },\n            {\n                label: \"C\",\n                text: \"To eliminate the need for AWS access credentials.\"\n            },\n            {\n                label: \"D\",\n                text: \"To accelerate Docker image compile times.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Remote state locking prevents race conditions and state corruption by acquiring a mutex lock (e.g. in DynamoDB) while `terraform apply` executes.\",\n        source: \"IndiaBIX Technical Interview - Cloud Infrastructure\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-03\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Cloud Networking\",\n        subSkill: \"AWS VPC\",\n        topic: \"Public vs Private Subnet Routing\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"In an Amazon VPC, what distinguishes a public subnet from a private subnet in its associated route table configuration?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"A public subnet contains a default route (`0.0.0.0/0`) directed to an Internet Gateway (IGW).\"\n            },\n            {\n                label: \"B\",\n                text: \"A public subnet has encryption permanently disabled.\"\n            },\n            {\n                label: \"C\",\n                text: \"A private subnet cannot have an IPv4 CIDR block assigned.\"\n            },\n            {\n                label: \"D\",\n                text: \"A public subnet bypasses all Network Access Control Lists (NACLs).\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"A subnet is defined as public if its route table explicitly routes outbound traffic destined for `0.0.0.0/0` through an Internet Gateway (IGW) attached to the VPC.\",\n        source: \"IndiaBIX Technical Interview - Networking & Cloud\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-04\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Kubernetes\",\n        subSkill: \"Workload Controllers\",\n        topic: \"DaemonSet vs Deployment\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"When deploying a cluster-wide log collector agent (like Fluentd) or node monitoring daemon (like node-exporter) to Kubernetes, which workload resource type should be used?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"StatefulSet\"\n            },\n            {\n                label: \"B\",\n                text: \"DaemonSet\"\n            },\n            {\n                label: \"C\",\n                text: \"Job\"\n            },\n            {\n                label: \"D\",\n                text: \"HorizontalPodAutoscaler\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"A `DaemonSet` ensures that all (or eligible) nodes in the Kubernetes cluster run exactly one copy of a Pod, making it ideal for storage daemons, log collectors, and node monitors.\",\n        source: \"IndiaBIX Technical Interview - Container Orchestration\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-05\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Kubernetes\",\n        subSkill: \"Networking\",\n        topic: \"Service Types (ClusterIP vs NodePort vs LoadBalancer)\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"What is the default Service type in Kubernetes that provides an internal virtual IP reachable only from within the cluster?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"NodePort\"\n            },\n            {\n                label: \"B\",\n                text: \"ClusterIP\"\n            },\n            {\n                label: \"C\",\n                text: \"LoadBalancer\"\n            },\n            {\n                label: \"D\",\n                text: \"ExternalName\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`ClusterIP` is the default Kubernetes Service type. It exposes the service on an internal IP address reachable only from within the cluster.\",\n        source: \"IndiaBIX Technical Interview - Kubernetes Networking\",\n        sourceUrl: \"https://www.indiabix.com/technical/networking/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-06\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"CI/CD Pipelines\",\n        subSkill: \"Optimization\",\n        topic: \"GitHub Actions Caching\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"How does caching `node_modules` or Docker build layers via `actions/cache` in GitHub Actions accelerate workflow runtimes?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"It bypasses all linting and test execution steps.\"\n            },\n            {\n                label: \"B\",\n                text: \"It restores unchanged dependencies from previous runs using hash keys (e.g. `hashFiles('**/package-lock.json')`) instead of downloading them across the internet every build.\"\n            },\n            {\n                label: \"C\",\n                text: \"It automatically scales up GitHub runner CPU cores.\"\n            },\n            {\n                label: \"D\",\n                text: \"It pushes production code directly to GitHub Pages.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`actions/cache` saves and restores dependencies between workflow runs keyed by lockfile hashes, avoiding repetitive network downloads and compilation overhead.\",\n        source: \"IndiaBIX Technical Interview - CI/CD Automation\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-07\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Linux Administration\",\n        subSkill: \"Service Management\",\n        topic: \"systemd & journalctl\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"Which Linux command displays live, streamed logs for a specific systemd service named `api-server` in real time?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"`ps -ef | grep api-server`\"\n            },\n            {\n                label: \"B\",\n                text: \"`journalctl -u api-server -f`\"\n            },\n            {\n                label: \"C\",\n                text: \"`top -u api-server`\"\n            },\n            {\n                label: \"D\",\n                text: \"`cat /etc/systemd/api-server.conf`\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`journalctl -u <unit> -f` queries the systemd journal logs filtered for a specific service unit and follows (-f) new entries in real time.\",\n        source: \"IndiaBIX Technical Interview - UNIX Process & System Management\",\n        sourceUrl: \"https://www.indiabix.com/technical/unix-process-management/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-08\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Deployment Strategies\",\n        subSkill: \"Zero-Downtime\",\n        topic: \"Canary vs Blue-Green\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"How does a Canary deployment strategy differ from a Blue-Green deployment?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Canary routes a small percentage (e.g. 5%) of live traffic to the new version to monitor metrics before full rollout, whereas Blue-Green shifts 100% of traffic at once between two identical environments.\"\n            },\n            {\n                label: \"B\",\n                text: \"Canary requires taking the database offline for 15 minutes.\"\n            },\n            {\n                label: \"C\",\n                text: \"Blue-Green deployments do not support rollback.\"\n            },\n            {\n                label: \"D\",\n                text: \"Canary deployments only run on bare-metal servers.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Canary deployments gradually bleed a fraction of production traffic to the new version while observing error rates and latency. Blue-Green maintains two identical fleets and switches traffic instantaneously.\",\n        source: \"IndiaBIX Technical Interview - Release Engineering\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-09\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Observability\",\n        subSkill: \"Metrics Collection\",\n        topic: \"Prometheus Pull vs Push\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"What is the primary architectural model Prometheus uses to collect numerical time-series metrics from target application pods?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"A Pull model: the Prometheus server periodically scrapes HTTP endpoints (like `/metrics`) hosted by target applications at configured scrape intervals.\"\n            },\n            {\n                label: \"B\",\n                text: \"A Push model: every application pod continuously floods raw UDP packets to port 514.\"\n            },\n            {\n                label: \"C\",\n                text: \"An SSH tunnel: Prometheus logs in via root password and parses text files.\"\n            },\n            {\n                label: \"D\",\n                text: \"A physical USB connection to the hypervisor.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Prometheus relies on a pull-based scraping architecture. Targets expose their metrics in open-metrics text format over HTTP, which Prometheus discovers and polls periodically.\",\n        source: \"IndiaBIX Technical Interview - Systems Monitoring\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-mcq-10\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"GitOps\",\n        subSkill: \"Continuous Delivery\",\n        topic: \"Declarative Drift Detection (ArgoCD)\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"In a GitOps workflow managed by ArgoCD, what happens when a cluster engineer manually modifies a Kubernetes Deployment via `kubectl edit` in production?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"The cluster crashes immediately.\"\n            },\n            {\n                label: \"B\",\n                text: \"ArgoCD detects configuration drift against the Git source of truth and flags the application as 'OutOfSync', optionally self-healing by reverting the manual change.\"\n            },\n            {\n                label: \"C\",\n                text: \"Git automatically creates a new commit and merges it.\"\n            },\n            {\n                label: \"D\",\n                text: \"The engineer's SSH keys are deleted.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"Under GitOps, Git is the single source of truth. ArgoCD continuously reconciles cluster live state with Git repository manifests, detecting out-of-band drifts and restoring declarative desired state.\",\n        source: \"IndiaBIX Technical Interview - GitOps & Cloud Native\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    // 5 Fill-in-the-Blank\n    {\n        id: \"do-fib-11\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Orchestration\",\n        subSkill: \"Kubernetes\",\n        topic: \"Container Orchestration Engine\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"Name the open-source container orchestration system originally designed by Google (often abbreviated as K8s) that automates deploying, scaling, and managing containerized applications.\",\n        acceptedAnswers: [\n            \"Kubernetes\",\n            \"kubernetes\",\n            \"K8s\",\n            \"k8s\"\n        ],\n        correctAnswer: \"Kubernetes\",\n        explanation: \"Kubernetes (K8s) is the industry-standard container orchestration platform maintained by the Cloud Native Computing Foundation (CNCF).\",\n        source: \"IndiaBIX Technical Interview - Cloud Computing\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-fib-12\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Infrastructure as Code\",\n        subSkill: \"Tooling\",\n        topic: \"Declarative IaC Tool\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"Name the popular open-source Infrastructure as Code software tool created by HashiCorp that uses HashiCorp Configuration Language (HCL) to provision multi-cloud resources.\",\n        acceptedAnswers: [\n            \"Terraform\",\n            \"terraform\"\n        ],\n        correctAnswer: \"Terraform\",\n        explanation: \"Terraform provides declarative configuration files to provision, update, and version cloud infrastructure across AWS, Azure, Google Cloud, and on-premises environments.\",\n        source: \"IndiaBIX Technical Interview - Cloud Infrastructure\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-fib-13\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Kubernetes\",\n        subSkill: \"Package Management\",\n        topic: \"K8s Package Manager\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Name the dedicated package manager for Kubernetes that utilizes structured packages termed 'Charts' to simplify defining, versioning, and deploying complex microservice topologies.\",\n        acceptedAnswers: [\n            \"Helm\",\n            \"helm\"\n        ],\n        correctAnswer: \"Helm\",\n        explanation: \"Helm is the package manager for Kubernetes that streamlines application deployment by packaging templates, default configuration values, and dependencies into reproducible charts.\",\n        source: \"IndiaBIX Technical Interview - Kubernetes Tools\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-fib-14\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Cloud Networking\",\n        subSkill: \"AWS VPC\",\n        topic: \"Outbound Internet Translation\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"What managed AWS networking service enables EC2 instances in a private subnet to establish outbound internet connections for software patches while blocking all inbound internet connections?\",\n        acceptedAnswers: [\n            \"NAT Gateway\",\n            \"nat gateway\",\n            \"NAT\",\n            \"AWS NAT Gateway\"\n        ],\n        correctAnswer: \"NAT Gateway\",\n        explanation: \"A Network Address Translation (NAT) Gateway resides in a public subnet, forwarding outbound traffic from private subnets to the Internet Gateway while disallowing unsolicited incoming requests.\",\n        source: \"IndiaBIX Technical Interview - Cloud Networking\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"do-fib-15\",\n        roleId: \"devops-engineer\",\n        role: \"Cloud & DevOps Engineer\",\n        skill: \"Linux Internals\",\n        subSkill: \"Virtualization\",\n        topic: \"Process Visibility Isolation\",\n        difficulty: \"Advanced\",\n        type: \"fill_blank\",\n        question: \"Which Linux kernel feature provides process isolation by creating distinct virtualized views of system resources like Process IDs (`pid`), Mounts (`mnt`), and Network interfaces (`net`) for containers?\",\n        acceptedAnswers: [\n            \"Namespaces\",\n            \"namespaces\",\n            \"Linux Namespaces\",\n            \"namespace\"\n        ],\n        correctAnswer: \"Namespaces\",\n        explanation: \"Linux namespaces wrap global system resources into isolated abstractions, ensuring processes in one container cannot see or interact with processes in another container.\",\n        source: \"IndiaBIX Technical Interview - UNIX & Operating Systems\",\n        sourceUrl: \"https://www.indiabix.com/technical/operating-systems/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/questions/technical/cloudDevops.ts\n");

