eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   CYBERSECURITY_QUESTIONS: () => (/* binding */ CYBERSECURITY_QUESTIONS)\n/* harmony export */ });\nconst CYBERSECURITY_QUESTIONS = [\n    // 10 MCQs\n    {\n        id: \"sec-mcq-01\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Threat Frameworks\",\n        subSkill: \"Adversary Profiling\",\n        topic: \"MITRE ATT&CK Structure\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"In the MITRE ATT&CK framework, what represents the adversary's overarching tactical goal (the 'why'), such as Initial Access, Persistence, or Exfiltration?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Tactics\"\n            },\n            {\n                label: \"B\",\n                text: \"Techniques\"\n            },\n            {\n                label: \"C\",\n                text: \"Procedures\"\n            },\n            {\n                label: \"D\",\n                text: \"Sub-techniques\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Tactics represent the 'why' (the adversary's objective, e.g., Persistence or Lateral Movement). Techniques represent 'how' the adversary achieves that tactical objective.\",\n        source: \"IndiaBIX Technical Interview - Cybersecurity Concepts\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-02\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Network Forensics\",\n        subSkill: \"TCP Protocols\",\n        topic: \"TCP Handshake Port Scanning\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"During a Wireshark packet capture analysis, an analyst observes thousands of sequential SYN packets sent to consecutive destination ports without any final ACK packets. What network activity does this indicate?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"A standard TLS session renegotiation.\"\n            },\n            {\n                label: \"B\",\n                text: \"A TCP SYN stealth port scan (half-open scanning).\"\n            },\n            {\n                label: \"C\",\n                text: \"Normal DNS resolution traffic.\"\n            },\n            {\n                label: \"D\",\n                text: \"A successful SSH file transfer.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"A TCP SYN scan (half-open scan) sends SYN packets across target ports. Open ports reply with SYN-ACK; the scanner then sends RST instead of ACK to close the connection without completing the 3-way handshake.\",\n        source: \"IndiaBIX Technical Interview - Computer Networks & Security\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-03\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Email Security\",\n        subSkill: \"Anti-Spoofing Protocols\",\n        topic: \"SPF vs DKIM vs DMARC\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"Which email security protocol uses cryptographic public/private key pairs to verify that an email message was not tampered with in transit?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"DKIM (DomainKeys Identified Mail)\"\n            },\n            {\n                label: \"B\",\n                text: \"SPF (Sender Policy Framework)\"\n            },\n            {\n                label: \"C\",\n                text: \"IMAP (Internet Message Access Protocol)\"\n            },\n            {\n                label: \"D\",\n                text: \"POP3\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"DKIM attaches a digital signature to email headers. Receiving mail servers verify the signature against the sender's public key published in DNS, proving email integrity.\",\n        source: \"IndiaBIX Technical Interview - Network Security Protocols\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-04\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Security Architecture\",\n        subSkill: \"Network Defense\",\n        topic: \"Demilitarized Zone (DMZ)\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"Why do enterprise network engineers place public-facing web servers in a Demilitarized Zone (DMZ) isolated between two firewalls?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"To give web servers direct administrative root access to domain controllers.\"\n            },\n            {\n                label: \"B\",\n                text: \"To prevent an adversary who compromises a public web server from directly traversing into the internal private corporate network.\"\n            },\n            {\n                label: \"C\",\n                text: \"To speed up public broadband internet downloads.\"\n            },\n            {\n                label: \"D\",\n                text: \"To eliminate the need for HTTPS encryption.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"A DMZ acts as a buffer network. If a public-facing web server is compromised, strict firewall policies prevent the attacker from pivoting directly into sensitive internal databases and corporate LAN segments.\",\n        source: \"IndiaBIX Technical Interview - Firewall & Network Architecture\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-05\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Threat Detection\",\n        subSkill: \"SIEM Analytics\",\n        topic: \"Correlation Rules & Alert Tuning\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"In a SIEM platform (like Splunk or Microsoft Sentinel), which correlation rule best identifies a potential brute-force password spraying attack?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"10 successful logins from the same employee workstation within 8 hours.\"\n            },\n            {\n                label: \"B\",\n                text: \"A single IP address generating failed login attempts (Event ID 4625) across 50 distinct usernames within a 5-minute window.\"\n            },\n            {\n                label: \"C\",\n                text: \"An automated scheduled cron job backing up database tables at midnight.\"\n            },\n            {\n                label: \"D\",\n                text: \"An engineer pinging their home router from a remote branch.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"Password spraying tries a small set of common passwords across many user accounts to bypass individual account lockout thresholds. Correlating high failures across distinct accounts from one IP flags this attack.\",\n        source: \"IndiaBIX Technical Interview - Security Operations & SIEM\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-06\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Incident Response\",\n        subSkill: \"NIST Lifecycle\",\n        topic: \"Containment Strategies\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"According to NIST SP 800-61, once a ransomware infection is confirmed on an active workstation, what is the immediate containment priority for the SOC analyst?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Isolate the compromised endpoint from the network immediately (disconnect Ethernet / disable Wi-Fi) while keeping power on to preserve volatile RAM memory for forensics.\"\n            },\n            {\n                label: \"B\",\n                text: \"Unplug the computer from the wall instantly, destroying volatile memory.\"\n            },\n            {\n                label: \"C\",\n                text: \"Send an email to the ransomware extortion address.\"\n            },\n            {\n                label: \"D\",\n                text: \"Format all hard drives across the entire department.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Network isolation halts lateral movement and C2 encryption commands. Preserving device power keeps volatile RAM intact, allowing forensic investigators to extract encryption keys, active process trees, and network sockets.\",\n        source: \"IndiaBIX Technical Interview - Incident Response Protocols\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-07\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Vulnerability Management\",\n        subSkill: \"CVSS Metrics\",\n        topic: \"Base Score Impact Dimensions\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"In the Common Vulnerability Scoring System (CVSS v3.1), which three security impact metrics compose the CIA triad evaluation?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Confidentiality, Integrity, and Availability\"\n            },\n            {\n                label: \"B\",\n                text: \"CPU, IP address, and Access\"\n            },\n            {\n                label: \"C\",\n                text: \"Cost, Infrastructure, and Architecture\"\n            },\n            {\n                label: \"D\",\n                text: \"Classification, Identity, and Audit\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"The CIA triad—Confidentiality, Integrity, and Availability—measures the potential degree of damage resulting from a successfully exploited vulnerability in CVSS base scoring.\",\n        source: \"IndiaBIX Technical Interview - Information Security Fundamentals\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-08\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Malware Analysis\",\n        subSkill: \"Command & Control\",\n        topic: \"DNS Tunneling Detection\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"How does a SOC analyst identify DNS tunneling used by malware for data exfiltration during SIEM log inspection?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"By observing high volumes of abnormally long, high-entropy subdomain requests (e.g. `a8f93e2b10.attacker.com`) querying external nameservers with high TXT record payload sizes.\"\n            },\n            {\n                label: \"B\",\n                text: \"By checking if DNS packets are formatted in UTF-8.\"\n            },\n            {\n                label: \"C\",\n                text: \"By noting that the DNS server uses UDP port 53.\"\n            },\n            {\n                label: \"D\",\n                text: \"By observing that all internal machines have DNS resolution enabled.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"DNS tunneling encodes exfiltrated files or C2 instructions into base64/hex subdomain strings. It produces unusually long queries with high character entropy and large volumes of TXT/NULL lookups.\",\n        source: \"IndiaBIX Technical Interview - Network Forensics\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-09\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Zero Trust Architecture\",\n        subSkill: \"Access Control\",\n        topic: \"Core Principles\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"What is the foundational paradigm of Zero Trust Architecture (NIST SP 800-207) compared to perimeter-based network security?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"No user or device inside or outside the network perimeter is trusted by default; all access requests must be continuously authenticated, authorized, and encrypted based on real-time context.\"\n            },\n            {\n                label: \"B\",\n                text: \"Internal LAN users have full unrestricted access without passwords.\"\n            },\n            {\n                label: \"C\",\n                text: \"Firewalls are completely replaced with biometric retina scanners.\"\n            },\n            {\n                label: \"D\",\n                text: \"Employees must change their passwords every 60 seconds.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Zero Trust assumes breach and treats internal networks as untrusted. Access decisions evaluate device health, user identity, contextual signals, and adhere to least-privilege principles continuously.\",\n        source: \"IndiaBIX Technical Interview - Enterprise Security Architecture\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-mcq-10\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Threat Hunting\",\n        subSkill: \"Lateral Movement\",\n        topic: \"Pass-the-Hash Attacks\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"In an Active Directory Windows enterprise environment, how does an adversary execute a 'Pass-the-Hash' attack?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"By extracting NTLM password hashes from memory (e.g. LSASS) and authenticating directly to other network hosts via SMB/RPC without ever cracking the plain-text password.\"\n            },\n            {\n                label: \"B\",\n                text: \"By sending phishing emails with malicious macros.\"\n            },\n            {\n                label: \"C\",\n                text: \"By modifying DNS records on domain controllers.\"\n            },\n            {\n                label: \"D\",\n                text: \"By overloading Kerberos servers with SYN flood packets.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"NTLM protocols accept the password hash directly during challenge-response authentication. An attacker who harvests NTLM hashes from memory can authenticate laterally across the domain without cracking the plain text.\",\n        source: \"IndiaBIX Technical Interview - Windows Security & Active Directory\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    // 5 Fill-in-the-Blank\n    {\n        id: \"sec-fib-11\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Security Operations\",\n        subSkill: \"SIEM Systems\",\n        topic: \"Centralized Security Telemetry\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"What is the four-letter acronym for centralized software platforms (like Splunk, QRadar, or Microsoft Sentinel) that aggregate, normalize, and correlate security logs across an enterprise?\",\n        acceptedAnswers: [\n            \"SIEM\",\n            \"siem\",\n            \"Security Information and Event Management\"\n        ],\n        correctAnswer: \"SIEM\",\n        explanation: \"SIEM (Security Information and Event Management) technology provides real-time analysis of security alerts generated by applications and network hardware.\",\n        source: \"IndiaBIX Technical Interview - Cybersecurity Operations\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-fib-12\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Packet Analysis\",\n        subSkill: \"Network Forensics\",\n        topic: \"Packet Sniffer Tool\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"Name the world's most widely-used open-source network protocol and packet analyzer tool featuring a distinctive blue shark fin logo.\",\n        acceptedAnswers: [\n            \"Wireshark\",\n            \"wireshark\"\n        ],\n        correctAnswer: \"Wireshark\",\n        explanation: \"Wireshark is the standard packet capture and deep network inspection utility used by network and security engineers globally.\",\n        source: \"IndiaBIX Technical Interview - Network Tools\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-fib-13\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Threat Frameworks\",\n        subSkill: \"Adversary Matrix\",\n        topic: \"MITRE ATT&CK Matrix\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Name the globally-accessible knowledge base and matrix of cyber adversary tactics and techniques curated by the MITRE corporation based on real-world observations.\",\n        acceptedAnswers: [\n            \"MITRE ATT&CK\",\n            \"ATT&CK\",\n            \"mitre att&ck\",\n            \"att&ck\"\n        ],\n        correctAnswer: \"MITRE ATT&CK\",\n        explanation: \"MITRE ATT&CK is a curated knowledge base used as a foundation for developing threat models and defensive methodologies in cybersecurity.\",\n        source: \"IndiaBIX Technical Interview - Threat Intelligence\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-fib-14\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Email Security\",\n        subSkill: \"DNS Records\",\n        topic: \"Sender Authorization Framework\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"What is the three-letter acronym for the DNS TXT record protocol that specifies which authorized mail server IP addresses are permitted to send emails on behalf of your domain?\",\n        acceptedAnswers: [\n            \"SPF\",\n            \"spf\",\n            \"Sender Policy Framework\"\n        ],\n        correctAnswer: \"SPF\",\n        explanation: \"SPF (Sender Policy Framework) is an email authentication method designed to detect and prevent spammers from sending messages on behalf of your domain.\",\n        source: \"IndiaBIX Technical Interview - Network Security\",\n        sourceUrl: \"https://www.indiabix.com/networking/questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"sec-fib-15\",\n        roleId: \"security-analyst\",\n        role: \"Cybersecurity Analyst / SOC Analyst\",\n        skill: \"Vulnerability Management\",\n        subSkill: \"Severity Scoring\",\n        topic: \"Vulnerability Severity Rating\",\n        difficulty: \"Advanced\",\n        type: \"fill_blank\",\n        question: \"What is the four-letter acronym for the open industry standard framework used to assign numerical severity ratings (ranging from 0.0 to 10.0) to discovered software security vulnerabilities?\",\n        acceptedAnswers: [\n            \"CVSS\",\n            \"cvss\",\n            \"Common Vulnerability Scoring System\"\n        ],\n        correctAnswer: \"CVSS\",\n        explanation: \"The Common Vulnerability Scoring System (CVSS) provides a standardized way to capture the principal characteristics of a vulnerability and produce a numerical score reflecting severity.\",\n        source: \"IndiaBIX Technical Interview - Vulnerability Management\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/questions/technical/cybersecurity.ts\n");

