eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   FRONTEND_QUESTIONS: () => (/* binding */ FRONTEND_QUESTIONS)\n/* harmony export */ });\nconst FRONTEND_QUESTIONS = [\n    // 10 MCQs\n    {\n        id: \"fe-mcq-01\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"CSS\",\n        subSkill: \"Layouts\",\n        topic: \"Flexbox Main vs Cross Axis\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"In a CSS Flexbox container with `flex-direction: row`, which property aligns flex items along the cross (vertical) axis?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"justify-content\"\n            },\n            {\n                label: \"B\",\n                text: \"align-items\"\n            },\n            {\n                label: \"C\",\n                text: \"flex-wrap\"\n            },\n            {\n                label: \"D\",\n                text: \"align-content-start\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`align-items` determines the default alignment of flex items along the cross axis (vertical when flex-direction is row). `justify-content` governs the main axis.\",\n        source: \"IndiaBIX Technical Interview - Web Technologies\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-02\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"Accessibility\",\n        subSkill: \"WCAG Standards\",\n        topic: \"Screen Reader Live Announcements\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"Which ARIA attribute should be added to an alert message or notification banner so screen readers announce dynamic text updates to visually impaired users?\",\n        options: [\n            {\n                label: \"A\",\n                text: 'aria-hidden=\"true\"'\n            },\n            {\n                label: \"B\",\n                text: 'aria-live=\"polite\"'\n            },\n            {\n                label: \"C\",\n                text: 'role=\"presentation\"'\n            },\n            {\n                label: \"D\",\n                text: 'tabindex=\"-1\"'\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: '`aria-live=\"polite\"` (or \"assertive\") turns an element into a live region, prompting assistive technologies to announce DOM text updates as they occur.',\n        source: \"IndiaBIX Technical Interview - Web Standards & Accessibility\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-03\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"JavaScript\",\n        subSkill: \"DOM Events\",\n        topic: \"Event Propagation\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"When a user clicks a button nested inside a card component, what is the effect of calling `event.stopPropagation()` inside the button's click handler?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"It prevents the browser's default behavior, such as submitting a form or following an anchor tag.\"\n            },\n            {\n                label: \"B\",\n                text: \"It stops the click event from bubbling up the DOM hierarchy to parent listener elements.\"\n            },\n            {\n                label: \"C\",\n                text: \"It permanently unmounts the component from the DOM tree.\"\n            },\n            {\n                label: \"D\",\n                text: \"It prevents other event handlers on the same button from executing.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`event.stopPropagation()` halts the upward (bubbling) or downward (capturing) propagation of the event through the DOM tree.\",\n        source: \"IndiaBIX Technical Interview - Core JavaScript\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-04\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"React\",\n        subSkill: \"Reconciliation\",\n        topic: \"Key Prop Importance\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"Why does React require a unique, stable `key` prop when rendering dynamic arrays of elements?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"To directly assign unique CSS class selectors to rendered HTML elements.\"\n            },\n            {\n                label: \"B\",\n                text: \"To identify which items in the list have changed, been added, or been removed during Virtual DOM diffing.\"\n            },\n            {\n                label: \"C\",\n                text: \"To automatically sort items alphanumerically before rendering.\"\n            },\n            {\n                label: \"D\",\n                text: \"To bind an automatic Redux state dispatcher to each list item.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"Keys enable React's reconciliation algorithm to distinguish items between render cycles. Stable keys preserve element state and avoid recreating DOM nodes.\",\n        source: \"IndiaBIX Technical Interview - Web Frameworks\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-05\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"Browser Performance\",\n        subSkill: \"Rendering Pipeline\",\n        topic: \"Reflow vs Repaint\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"Which of the following CSS property changes will trigger a complete browser Layout (Reflow) step instead of only a Repaint?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Changing `background-color` from white to navy\"\n            },\n            {\n                label: \"B\",\n                text: \"Modifying `width` or `padding` of an element\"\n            },\n            {\n                label: \"C\",\n                text: \"Altering `visibility` from hidden to visible\"\n            },\n            {\n                label: \"D\",\n                text: \"Updating `color` of typography\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"Properties affecting element geometry or box model dimensions (width, height, padding, margin) force the browser to recalculate the positions and sizes of all influenced elements (reflow).\",\n        source: \"IndiaBIX Technical Interview - Browser Internals\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-06\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"TypeScript\",\n        subSkill: \"Generics\",\n        topic: \"Generic Component Props\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"In a TypeScript React application, how do you type a reusable `SelectDropdown` component so its `onChange` value matches the exact type of its `items` array elements?\",\n        codeSnippet: `interface SelectProps<T> {\n  items: T[];\n  selectedItem: T;\n  onSelect: (item: T) => void;\n}`,\n        options: [\n            {\n                label: \"A\",\n                text: \"By using TypeScript generic parameter `<T>` on the component props definition.\"\n            },\n            {\n                label: \"B\",\n                text: \"By casting every item to `any` inside the event callback.\"\n            },\n            {\n                label: \"C\",\n                text: \"By relying exclusively on runtime `typeof` checks.\"\n            },\n            {\n                label: \"D\",\n                text: \"By hardcoding `items: string[]` in the interface.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Generic type parameters `<T>` capture the item type upon component usage, ensuring strict end-to-end type safety between the selected item and the onSelect handler.\",\n        source: \"IndiaBIX Technical Interview - TypeScript & OOP\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-07\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"CSS\",\n        subSkill: \"Cascading Specificity\",\n        topic: \"Specificity Weight Calculation\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"Which of the following CSS selectors possesses the highest cascading specificity weight?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"`div.container p.description`\"\n            },\n            {\n                label: \"B\",\n                text: \"`#header nav ul li`\"\n            },\n            {\n                label: \"C\",\n                text: \"`button:hover`\"\n            },\n            {\n                label: \"D\",\n                text: \"`main > section > article`\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`#header nav ul li` contains 1 ID selector (1-0-0) and 3 element selectors (0-0-3), yielding specificity (1, 0, 3), which easily overrides class-level selectors.\",\n        source: \"IndiaBIX Technical Interview - CSS Mastery\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-08\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"Performance\",\n        subSkill: \"Core Web Vitals\",\n        topic: \"Cumulative Layout Shift (CLS)\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"What is the primary cause of a poor Cumulative Layout Shift (CLS) score on a modern web application?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Large JavaScript bundle execution blocking the main thread during boot.\"\n            },\n            {\n                label: \"B\",\n                text: \"Images, video embeds, or ad iframes rendered without explicit `width` and `height` aspect-ratio dimensions.\"\n            },\n            {\n                label: \"C\",\n                text: \"High server response latency (Time to First Byte).\"\n            },\n            {\n                label: \"D\",\n                text: \"Using WebGL shaders on mobile screens.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"When images or dynamic elements load without declared dimensions, the browser cannot reserve vertical space in the layout, causing content below to abruptly shift down.\",\n        source: \"IndiaBIX Technical Interview - Web Performance\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-09\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"React\",\n        subSkill: \"Next.js Architecture\",\n        topic: \"Server Component Boundary\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"In Next.js App Router, which statement regarding React Server Components (RSC) vs Client Components is accurate?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Client Components cannot be imported inside Server Components under any circumstances.\"\n            },\n            {\n                label: \"B\",\n                text: \"Server Components do not ship their JavaScript code to the client bundle, reducing bundle size and executing purely on the server.\"\n            },\n            {\n                label: \"C\",\n                text: \"Server Components support `useState` and `useEffect` hooks natively without directives.\"\n            },\n            {\n                label: \"D\",\n                text: \"Adding `'use client'` compiles the component into WebAssembly.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"React Server Components run exclusively on the server, streaming HTML and serialized UI instructions without bundling their source code into the client JavaScript payload.\",\n        source: \"IndiaBIX Technical Interview - Modern Frameworks\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-mcq-10\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"Browser APIs\",\n        subSkill: \"Viewport Observation\",\n        topic: \"Intersection Observer API\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"Why is the `IntersectionObserver` API vastly superior to listening to the `window.onscroll` event for infinite scrolling and lazy-loading images?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"IntersectionObserver runs asynchronously off the main thread without causing continuous layout thrashing on every scroll tick.\"\n            },\n            {\n                label: \"B\",\n                text: \"IntersectionObserver automatically compresses JPG images into AVIF formats.\"\n            },\n            {\n                label: \"C\",\n                text: \"It prevents cross-origin iframe security violations.\"\n            },\n            {\n                label: \"D\",\n                text: \"It forces the browser GPU to render all hidden items simultaneously.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"`IntersectionObserver` notifies scripts asynchronously when an element enters or exits the viewport, eliminating synchronous `getBoundingClientRect()` calls that cause layout thrashing in scroll listeners.\",\n        source: \"IndiaBIX Technical Interview - Browser Web APIs\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    // 5 Fill-in-the-Blank\n    {\n        id: \"fe-fib-11\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"CSS\",\n        subSkill: \"Responsive Typography\",\n        topic: \"Root Font Sizing Unit\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"Which three-letter CSS relative measurement unit scales proportionally relative to the font-size of the root `<html>` element?\",\n        acceptedAnswers: [\n            \"rem\",\n            \"rem unit\",\n            \"rems\"\n        ],\n        correctAnswer: \"rem\",\n        explanation: \"`rem` (root em) computes its pixel value based on the root `<html>` font-size (typically 16px by default), making accessibility scaling seamless.\",\n        source: \"IndiaBIX Technical Interview - CSS Standards\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-fib-12\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"JavaScript\",\n        subSkill: \"Data Serialization\",\n        topic: \"JSON Deserialization\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"Which standard JavaScript built-in method parses a JSON formatted string and constructs the corresponding JavaScript object or value?\",\n        acceptedAnswers: [\n            \"JSON.parse\",\n            \"JSON.parse()\",\n            \"json.parse\"\n        ],\n        correctAnswer: \"JSON.parse\",\n        explanation: \"`JSON.parse(text)` takes a valid JSON string and deserializes it into JavaScript primitive or object types.\",\n        source: \"IndiaBIX Technical Interview - Core JavaScript\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-fib-13\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"React\",\n        subSkill: \"Refs and DOM\",\n        topic: \"Persistent Mutable Reference\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Which React hook returns a mutable object with a `.current` property that persists across renders without triggering a re-render when mutated?\",\n        acceptedAnswers: [\n            \"useRef\",\n            \"useRef()\",\n            \"use-ref\"\n        ],\n        correctAnswer: \"useRef\",\n        explanation: \"`useRef` creates a persistent reference container across renders commonly used to reference underlying DOM nodes or store timers without inducing re-renders.\",\n        source: \"IndiaBIX Technical Interview - React Hooks\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-fib-14\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"CSS\",\n        subSkill: \"Animations\",\n        topic: \"Hardware Layer Promotion\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Which CSS property is applied to tell the browser in advance that an element will undergo transformation, promoting it to a GPU composited layer (e.g. `___: transform;`)?\",\n        acceptedAnswers: [\n            \"will-change\",\n            \"will-change property\"\n        ],\n        correctAnswer: \"will-change\",\n        explanation: \"`will-change: transform` hints to the browser engine to allocate a dedicated GPU compositor layer before animation begins, avoiding jank.\",\n        source: \"IndiaBIX Technical Interview - CSS Performance\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fe-fib-15\",\n        roleId: \"frontend-dev\",\n        role: \"Frontend Developer\",\n        skill: \"Performance\",\n        subSkill: \"Core Web Vitals\",\n        topic: \"Interaction Responsiveness Metric\",\n        difficulty: \"Advanced\",\n        type: \"fill_blank\",\n        question: \"What is the three-letter acronym for the Core Web Vital metric that replaced First Input Delay (FID) to assess page interaction responsiveness throughout the entire page lifecycle?\",\n        acceptedAnswers: [\n            \"INP\",\n            \"Interaction to Next Paint\",\n            \"inp\"\n        ],\n        correctAnswer: \"INP\",\n        explanation: \"INP (Interaction to Next Paint) measures the latency of all discrete user interactions (clicks, taps, keypresses) across the entire session lifecycle.\",\n        source: \"IndiaBIX Technical Interview - Web Performance Metrics\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/questions/technical/frontend.ts\n");

