eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   FULL_STACK_QUESTIONS: () => (/* binding */ FULL_STACK_QUESTIONS)\n/* harmony export */ });\nconst FULL_STACK_QUESTIONS = [\n    // 10 MCQs\n    {\n        id: \"fs-mcq-01\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"REST APIs\",\n        subSkill: \"HTTP Protocols\",\n        topic: \"HTTP Status Codes\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"When a client sends a POST request that successfully creates a new user entity in the database, which standard HTTP status code should the server return?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"200 OK\"\n            },\n            {\n                label: \"B\",\n                text: \"201 Created\"\n            },\n            {\n                label: \"C\",\n                text: \"204 No Content\"\n            },\n            {\n                label: \"D\",\n                text: \"202 Accepted\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"HTTP 201 Created indicates that the request succeeded and led to the creation of a new resource on the server, typically returning the URI in the Location header.\",\n        source: \"IndiaBIX Technical Interview - Web Technologies\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-02\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Node.js\",\n        subSkill: \"Package Management\",\n        topic: \"Dependency Tree Locking\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"In a Node.js full-stack repository, what is the primary role of `package-lock.json` alongside `package.json`?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"It compiles TypeScript source code into bundle files during npm install.\"\n            },\n            {\n                label: \"B\",\n                text: \"It locks the exact resolved dependency versions and transitive sub-dependencies across all developer environments.\"\n            },\n            {\n                label: \"C\",\n                text: \"It stores secret environment credentials and database connection strings.\"\n            },\n            {\n                label: \"D\",\n                text: \"It replaces the need to run node_modules on production servers.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`package-lock.json` pins the exact version of every installed package and its nested dependencies, guaranteeing deterministic installs across CI/CD and developer machines.\",\n        source: \"IndiaBIX Technical Interview - Node.js\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-03\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Git\",\n        subSkill: \"Version Control Workflow\",\n        topic: \"Staging Index\",\n        difficulty: \"Beginner\",\n        type: \"mcq\",\n        question: \"Which Git command transfers modified working-tree files into the staging index in preparation for a commit?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"git push\"\n            },\n            {\n                label: \"B\",\n                text: \"git add\"\n            },\n            {\n                label: \"C\",\n                text: \"git stage-now\"\n            },\n            {\n                label: \"D\",\n                text: \"git commit -m\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`git add` updates the index using the current content of the working tree, staging changes for the next commit.\",\n        source: \"IndiaBIX Technical Interview - Software Engineering & Git\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-04\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"JavaScript\",\n        subSkill: \"Asynchronous Execution\",\n        topic: \"Event Loop Microtasks vs Macrotasks\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"What is the console output order for the following JavaScript snippet?\",\n        codeSnippet: `console.log(\"1\");\nsetTimeout(() => console.log(\"2\"), 0);\nPromise.resolve().then(() => console.log(\"3\")).then(() => console.log(\"4\"));\nconsole.log(\"5\");`,\n        options: [\n            {\n                label: \"A\",\n                text: \"1, 5, 3, 4, 2\"\n            },\n            {\n                label: \"B\",\n                text: \"1, 2, 3, 4, 5\"\n            },\n            {\n                label: \"C\",\n                text: \"1, 5, 2, 3, 4\"\n            },\n            {\n                label: \"D\",\n                text: \"1, 3, 5, 4, 2\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Synchronous code runs first ('1', '5'). The microtask queue (Promises: '3', then '4') is completely drained before any macrotask callback ('2' from setTimeout) is executed.\",\n        source: \"IndiaBIX Technical Interview - Core JavaScript\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-05\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"React\",\n        subSkill: \"Hook Optimization\",\n        topic: \"useCallback & Memoization\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"In React component optimization, what is the exact function of `useCallback`?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"It memoizes the computed numerical result of an expensive calculation.\"\n            },\n            {\n                label: \"B\",\n                text: \"It returns a memoized version of a callback function that only changes if specified dependencies change.\"\n            },\n            {\n                label: \"C\",\n                text: \"It executes a callback function immediately after paint completes.\"\n            },\n            {\n                label: \"D\",\n                text: \"It binds the function to the Window event listener without memory leaks.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`useCallback` caches a function reference between re-renders, preventing unwanted child component re-renders when the child is wrapped in `React.memo`.\",\n        source: \"IndiaBIX Technical Interview - Web Frameworks\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-06\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"PostgreSQL\",\n        subSkill: \"Query Optimization\",\n        topic: \"Composite Indexing\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"You frequently execute `SELECT id, total_amount FROM orders WHERE customer_id = $1 ORDER BY created_at DESC LIMIT 20`. Which index structure best optimizes this query by avoiding heap fetches?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"A hash index on `customer_id` only.\"\n            },\n            {\n                label: \"B\",\n                text: \"A composite B-Tree index on `(customer_id, created_at DESC) INCLUDE (id, total_amount)`.\"\n            },\n            {\n                label: \"C\",\n                text: \"Two separate single-column indexes on `id` and `total_amount`.\"\n            },\n            {\n                label: \"D\",\n                text: \"A GIN index on `created_at`.\"\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"A composite B-tree index on `(customer_id, created_at DESC)` satisfies the WHERE and ORDER BY clauses without sorting, and `INCLUDE` allows an index-only scan without reading table heap blocks.\",\n        source: \"IndiaBIX Technical Interview - Database Management\",\n        sourceUrl: \"https://www.indiabix.com/technical/dbms-basics/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-07\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Express\",\n        subSkill: \"Middleware Architecture\",\n        topic: \"Centralized Error Handling\",\n        difficulty: \"Intermediate\",\n        type: \"mcq\",\n        question: \"How does Express.js internally distinguish an error-handling middleware function from regular request middleware?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"By checking whether the function has exactly four declared parameters: `(err, req, res, next)` via `fn.length`.\"\n            },\n            {\n                label: \"B\",\n                text: \"By verifying that the middleware file is placed inside an `/errors` folder.\"\n            },\n            {\n                label: \"C\",\n                text: \"By inspecting if the function returns a JavaScript Error object instance.\"\n            },\n            {\n                label: \"D\",\n                text: \"By prefixing the route declaration with `app.catch()`.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Express inspects `fn.length === 4`. Functions with four arguments are treated specifically as error-handling middleware when `next(err)` is triggered.\",\n        source: \"IndiaBIX Technical Interview - Node.js & Express\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-08\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Authentication\",\n        subSkill: \"Web Security\",\n        topic: \"XSS Token Protection\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"What is the recommended browser storage mechanism for JSON Web Tokens (JWT) to mitigate token theft via Cross-Site Scripting (XSS)?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"In `window.localStorage` under an encrypted key.\"\n            },\n            {\n                label: \"B\",\n                text: \"In an `HttpOnly`, `Secure`, `SameSite` cookie.\"\n            },\n            {\n                label: \"C\",\n                text: \"In `window.sessionStorage`.\"\n            },\n            {\n                label: \"D\",\n                text: 'In a hidden `<input type=\"password\">` field in the DOM.'\n            }\n        ],\n        correctAnswer: \"B\",\n        explanation: \"`HttpOnly` cookies are inaccessible to client-side scripts, preventing malicious JavaScript from exfiltrating the token during an XSS attack.\",\n        source: \"IndiaBIX Technical Interview - Security & Networking\",\n        sourceUrl: \"https://www.indiabix.com/technical/networking/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-09\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"PostgreSQL\",\n        subSkill: \"Concurrency Control\",\n        topic: \"Transaction Isolation Levels\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"In an e-commerce checkout transaction, which database transaction isolation level prevents phantom reads and serialization anomalies by emulating serial transaction execution?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"Read Uncommitted\"\n            },\n            {\n                label: \"B\",\n                text: \"Read Committed\"\n            },\n            {\n                label: \"C\",\n                text: \"Repeatable Read\"\n            },\n            {\n                label: \"D\",\n                text: \"Serializable\"\n            }\n        ],\n        correctAnswer: \"D\",\n        explanation: \"The Serializable isolation level provides the highest tier of isolation. It monitors concurrent transactions to ensure the overall outcome is equivalent to executing them one after another.\",\n        source: \"IndiaBIX Technical Interview - DBMS & Transactions\",\n        sourceUrl: \"https://www.indiabix.com/technical/dbms/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-mcq-10\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Deployment\",\n        subSkill: \"Containerization\",\n        topic: \"Docker Multi-Stage Builds\",\n        difficulty: \"Advanced\",\n        type: \"mcq\",\n        question: \"Why are multi-stage Docker builds standard practice for containerizing full-stack Node.js / React applications?\",\n        options: [\n            {\n                label: \"A\",\n                text: \"They separate build tools and SDKs from the final runtime image, drastically reducing image size and attack surface.\"\n            },\n            {\n                label: \"B\",\n                text: \"They allow a single Docker container to run multiple operating systems concurrently.\"\n            },\n            {\n                label: \"C\",\n                text: \"They allow the container to bypass Docker daemon root permissions.\"\n            },\n            {\n                label: \"D\",\n                text: \"They enable instant compilation of C++ native binaries without compilers.\"\n            }\n        ],\n        correctAnswer: \"A\",\n        explanation: \"Multi-stage builds allow compiling frontend bundles and installing heavy build tools in an initial stage, then copying only the production artifacts into a lean minimal base image.\",\n        source: \"IndiaBIX Technical Interview - UNIX & Virtualization\",\n        sourceUrl: \"https://www.indiabix.com/technical/unix-process-management/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    // 5 Fill-in-the-Blank\n    {\n        id: \"fs-fib-11\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"HTML\",\n        subSkill: \"Document Head Metadata\",\n        topic: \"External Stylesheet Linking\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"In modern HTML5 documents, which tag element is placed inside the `<head>` to reference an external CSS stylesheet?\",\n        acceptedAnswers: [\n            \"<link>\",\n            \"link\",\n            \"link tag\",\n            \"<link/>\"\n        ],\n        correctAnswer: \"link\",\n        explanation: 'The `<link rel=\"stylesheet\" href=\"styles.css\">` tag connects external stylesheet resources to the HTML document.',\n        source: \"IndiaBIX Technical Interview - Web Technologies\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-fib-12\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"Node.js\",\n        subSkill: \"Runtimes\",\n        topic: \"Global Scope Identifier\",\n        difficulty: \"Beginner\",\n        type: \"fill_blank\",\n        question: \"In the Node.js server runtime environment, what is the top-level global scope object that serves as the counterpart to the browser's `window` object?\",\n        acceptedAnswers: [\n            \"global\",\n            \"globalThis\",\n            \"global object\"\n        ],\n        correctAnswer: \"global\",\n        explanation: \"`global` (or standard `globalThis`) provides the global namespace in Node.js where functions like `setTimeout`, `Buffer`, and `process` reside.\",\n        source: \"IndiaBIX Technical Interview - Node.js Fundamentals\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-fib-13\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"REST APIs\",\n        subSkill: \"HTTP Headers\",\n        topic: \"Content Negotiation\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Which HTTP request header does a REST client send to inform the server of the MIME media types it is capable of receiving in the response?\",\n        acceptedAnswers: [\n            \"Accept\",\n            \"accept-header\",\n            \"accept\"\n        ],\n        correctAnswer: \"Accept\",\n        explanation: \"The `Accept` request header (e.g. `Accept: application/json`) informs the server which content format the client expects in the response body.\",\n        source: \"IndiaBIX Technical Interview - Networking Protocols\",\n        sourceUrl: \"https://www.indiabix.com/technical/networking/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-fib-14\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"React\",\n        subSkill: \"Lifecycle Effects\",\n        topic: \"Side Effect Execution\",\n        difficulty: \"Intermediate\",\n        type: \"fill_blank\",\n        question: \"Which primary React built-in hook is utilized to synchronize component state with external systems like timers, subscriptions, or network requests after rendering?\",\n        acceptedAnswers: [\n            \"useEffect\",\n            \"use-effect\",\n            \"useEffect()\"\n        ],\n        correctAnswer: \"useEffect\",\n        explanation: \"`useEffect` schedules and executes side-effects after the component render commit phase has painted to the screen.\",\n        source: \"IndiaBIX Technical Interview - Modern Frontend Frameworks\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    },\n    {\n        id: \"fs-fib-15\",\n        roleId: \"full-stack-dev\",\n        role: \"Full Stack Developer\",\n        skill: \"System Design\",\n        subSkill: \"Architecture Patterns\",\n        topic: \"Command Query Separation\",\n        difficulty: \"Advanced\",\n        type: \"fill_blank\",\n        question: \"What is the four-letter acronym for the architectural pattern that segregates data modification operations (writes) from data retrieval operations (reads)?\",\n        acceptedAnswers: [\n            \"CQRS\",\n            \"cqrs\",\n            \"Command Query Responsibility Segregation\"\n        ],\n        correctAnswer: \"CQRS\",\n        explanation: \"CQRS (Command Query Responsibility Segregation) separates read models from write models, allowing independent scaling, optimization, and schemas for queries vs commands.\",\n        source: \"IndiaBIX Technical Interview - Distributed Architecture\",\n        sourceUrl: \"https://www.indiabix.com/technical/interview-questions-and-answers/\",\n        sourceType: \"original_based_on_reference\",\n        version: \"1.0\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/questions/technical/fullStack.ts\n");

